-- Section 1313: Reading Passage 3: Artificial artist?
INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(1313, 131, 'reading', 'Reading Passage 3: Artificial artist?', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
                                            Questions 27-31                                                                                                                                                
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <p>Choose the correct letter, <strong>A</strong>, <strong>B</strong>, <strong>C</strong> or <strong>D</strong>.</p>
<p><em>Write the correct letter in boxes on your answer sheet.</em></p>
                                        </div>
                                        <div class="ielts-reading-questions">
                                                                                                                                                                                            <div class="ielts-standalone-q" data-qnum="27"><div class="ielts-q-header"><strong class="ielts-q-badge">27</strong><span class="ielts-q-title"><span>What is the writer suggesting about computer-produced works in the first paragraph?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="27" name="question_27" value="A"><span class="ielts-radio-text"><strong>A</strong> People’s acceptance of them can vary considerably.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="27" name="question_27" value="B"><span class="ielts-radio-text"><strong>B</strong> A great deal of progress has already been attained in this field.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="27" name="question_27" value="C"><span class="ielts-radio-text"><strong>C</strong> They have had more success in some artistic genres than in others.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="27" name="question_27" value="D"><span class="ielts-radio-text"><strong>D</strong> the advances are not as significant as the public believes them to be.</span></label></div></div><div class="ielts-standalone-q" data-qnum="28"><div class="ielts-q-header"><strong class="ielts-q-badge">28</strong><span class="ielts-q-title"><span>According to Geraint Wiggins, why are many people worried by computer art?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="28" name="question_28" value="A"><span class="ielts-radio-text"><strong>A</strong> It is aesthetically inferior to human art.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="28" name="question_28" value="B"><span class="ielts-radio-text"><strong>B</strong> It may ultimately supersede human art.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="28" name="question_28" value="C"><span class="ielts-radio-text"><strong>C</strong> It undermines a fundamental human quality.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="28" name="question_28" value="D"><span class="ielts-radio-text"><strong>D</strong> It will lead to a deterioration in human ability.</span></label></div></div><div class="ielts-standalone-q" data-qnum="29"><div class="ielts-q-header"><strong class="ielts-q-badge">29</strong><span class="ielts-q-title"><span>What is a key difference between Aaron and the Painting Fool?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="29" name="question_29" value="A"><span class="ielts-radio-text"><strong>A</strong> its programmer’s background</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="29" name="question_29" value="B"><span class="ielts-radio-text"><strong>B</strong> public response to its work</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="29" name="question_29" value="C"><span class="ielts-radio-text"><strong>C</strong> the source of its subject matter</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="29" name="question_29" value="D"><span class="ielts-radio-text"><strong>D</strong> the technical standard of its output</span></label></div></div><div class="ielts-standalone-q" data-qnum="30"><div class="ielts-q-header"><strong class="ielts-q-badge">30</strong><span class="ielts-q-title"><span>What point does Simon Colton make in the fourth paragraph?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="30" name="question_30" value="A"><span class="ielts-radio-text"><strong>A</strong> Software-produced art is often dismissed as childish and simplistic.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="30" name="question_30" value="B"><span class="ielts-radio-text"><strong>B</strong> The same concepts of creativity should not be applied to all forms of art.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="30" name="question_30" value="C"><span class="ielts-radio-text"><strong>C</strong> It is unreasonable to expect a machine to be as imaginative as a human being.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="30" name="question_30" value="D"><span class="ielts-radio-text"><strong>D</strong> People tend to judge computer art and human art according to different criteria.</span></label></div></div><div class="ielts-standalone-q" data-qnum="31"><div class="ielts-q-header"><strong class="ielts-q-badge">31</strong><span class="ielts-q-title"><span>The writer refers to the paintings of a chair as an example of computer art which</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="31" name="question_31" value="A"><span class="ielts-radio-text"><strong>A</strong> achieves a particularly striking effect.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="31" name="question_31" value="B"><span class="ielts-radio-text"><strong>B</strong> exhibits a certain level of genuine artistic skill.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="31" name="question_31" value="C"><span class="ielts-radio-text"><strong>C</strong> closely resembles that of a well-known artist.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="31" name="question_31" value="D"><span class="ielts-radio-text"><strong>D</strong> highlights the technical limitations of the software.</span></label></div></div></div>
