-- Section 1323: Reading Passage 3: MAKING THE MOST OF TRENDS
INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(1323, 132, 'reading', 'Reading Passage 3: MAKING THE MOST OF TRENDS', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
                                            Questions 27-31                                                                                                                                                
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <p>Choose the correct letter, <strong>A</strong>, <strong>B</strong>, <strong>C</strong> or <strong>D</strong>.</p>
<p>Write the correct letter in boxes on your answer sheet.</p>
                                        </div>
                                        <div class="ielts-reading-questions">
                                                                                                                                                                                            <div class="ielts-standalone-q" data-qnum="27"><div class="ielts-q-header"><strong class="ielts-q-badge">27</strong><span class="ielts-q-title"><span>In the first paragraph, the writer says that most managers</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="27" name="question_27" value="A"><span class="ielts-radio-text"><strong>A</strong> fail to spot the key consumer trends of the moment.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="27" name="question_27" value="B"><span class="ielts-radio-text"><strong>B</strong> make the mistake of focusing only on the principal consumer trends.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="27" name="question_27" value="C"><span class="ielts-radio-text"><strong>C</strong> misinterpret market research data relating to current consumer trends.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="27" name="question_27" value="D"><span class="ielts-radio-text"><strong>D</strong> are unaware of the significant impact that trends have on consumers’ lives.</span></label></div></div><div class="ielts-standalone-q" data-qnum="28"><div class="ielts-q-header"><strong class="ielts-q-badge">28</strong><span class="ielts-q-title"><span>According to the third paragraph, Coach was anxious to</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="28" name="question_28" value="A"><span class="ielts-radio-text"><strong>A</strong> follow what some of its competitors were doing.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="28" name="question_28" value="B"><span class="ielts-radio-text"><strong>B</strong> maintain its prices throughout its range.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="28" name="question_28" value="C"><span class="ielts-radio-text"><strong>C</strong> safeguard its reputation as a manufacturer of luxury goods.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="28" name="question_28" value="D"><span class="ielts-radio-text"><strong>D</strong> modify the entire look of its brand to suit the economic climate.</span></label></div></div><div class="ielts-standalone-q" data-qnum="29"><div class="ielts-q-header"><strong class="ielts-q-badge">29</strong><span class="ielts-q-title"><span>What point is made about Tesco’s Greener Living programme?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="29" name="question_29" value="A"><span class="ielts-radio-text"><strong>A</strong> It did not require Tesco to modify its core business activities.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="29" name="question_29" value="B"><span class="ielts-radio-text"><strong>B</strong> It succeeded in attracting a more eco-conscious slientele.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="29" name="question_29" value="C"><span class="ielts-radio-text"><strong>C</strong> Its main aim was to raise consumers’ awareness of environmental issues.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="29" name="question_29" value="D"><span class="ielts-radio-text"><strong>D</strong> It was not the first time that Tesco had implemented such an initiative.</span></label></div></div><div class="ielts-standalone-q" data-qnum="30"><div class="ielts-q-header"><strong class="ielts-q-badge">30</strong><span class="ielts-q-title"><span>What does the writer suggest about Nike’s strategy?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="30" name="question_30" value="A"><span class="ielts-radio-text"><strong>A</strong> It was an extremely risky strategy at the time.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="30" name="question_30" value="B"><span class="ielts-radio-text"><strong>B</strong> It was a strategy that only a major company could afford to follow.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="30" name="question_30" value="C"><span class="ielts-radio-text"><strong>C</strong> It was the type of strategy that would not have been possible in the past.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="30" name="question_30" value="D"><span class="ielts-radio-text"><strong>D</strong> It was the kind of strategy which might appear to have few obvious benefits.</span></label></div></div><div class="ielts-standalone-q" data-qnum="31"><div class="ielts-q-header"><strong class="ielts-q-badge">31</strong><span class="ielts-q-title"><span>What was original about the ME2?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="31" name="question_31" value="A"><span class="ielts-radio-text"><strong>A</strong> It contained technology that had been developed for the sports industry.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="31" name="question_31" value="B"><span class="ielts-radio-text"><strong>B</strong> It appealed to young people who were keen to improve their physical fitness.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="31" name="question_31" value="C"><span class="ielts-radio-text"><strong>C</strong> It took advantage of a current trend for video games with colourful 3D graphic.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="31" name="question_31" value="D"><span class="ielts-radio-text"><strong>D</strong> It was a handheld game that addressed people’s concerns about unhealthy lifestyles.</span></label></div></div></div>
