-- Section 1332: Reading Passage 2: How baby talk gives infant brains a boost
INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(1332, 133, 'reading', 'Reading Passage 2: How baby talk gives infant brains a boost', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
                                            Questions 14-17                                                                                                                                                
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <p>Look at the following ideas and the list of researchers below.</p>
<p>Match each idea with the correct researcher, <strong>A</strong>, <strong>B</strong> or <strong>C</strong>.</p>
<p><em>Write the correct letter, <strong>A</strong>, <strong>B</strong> or <strong>C</strong>, in boxes on your answer sheet.</em></p>
<p><strong>NB</strong>  <em>You may use any letter more than once.</em></p>
<p><strong>List of Researchers</strong></p>
<p><strong>A</strong>          Mark VanDam</p>
<p><strong>B</strong>          Nairán Ramirez-Esparza</p>
<p><strong>C</strong>          Patricia Kuhl</p>
                                        </div>
                                        <div class="ielts-reading-questions">
                                                                                                                                                                                                <table class="ielts-reading-matching-table"><thead><tr><th></th><th>A</th><th>B</th><th>C</th></tr></thead><tbody><tr class="ielts-reading-question-item"><td class="ielts-reading-matching-question-cell"><strong id="ielts-reading-question-number-14" class="ielts-q-badge">14</strong> <span>the importance of adults giving babies individual attention when talking to them</span></td>
                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="14" name="question_14" value="A"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="14" name="question_14" value="B"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="14" name="question_14" value="C"></td></tr>                                                                                                                                                                                                                                                                                                    <tr class="ielts-reading-question-item"><td class="ielts-reading-matching-question-cell"><strong id="ielts-reading-question-number-15" class="ielts-q-badge">15</strong> <span>the connection between what babies hear and their own efforts to create speech</span></td>
                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="15" name="question_15" value="A"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="15" name="question_15" value="B"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="15" name="question_15" value="C"></td></tr>                                                                                                                                                                                                                                                                                                    <tr class="ielts-reading-question-item"><td class="ielts-reading-matching-question-cell"><strong id="ielts-reading-question-number-16" class="ielts-q-badge">16</strong> <span>the advantage for the baby of having two parents each speaking in a different way</span></td>
