                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="30" name="question_30" value="A"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="30" name="question_30" value="B"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="30" name="question_30" value="C"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="30" name="question_30" value="D"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="30" name="question_30" value="E"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="30" name="question_30" value="F"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="30" name="question_30" value="G"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="30" name="question_30" value="H"></td></tr>                                                                                                                                                                                                           