-- Section 1341: Reading Passage 1: Cutty Sark: the fastest sailing ship of all time
INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(1341, 134, 'reading', 'Reading Passage 1: Cutty Sark: the fastest sailing ship of all time', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
                                            Questions 1-8                                                                                                                                                                                                    
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <p>Do the following statements agree with the information given in the Reading Passage?</p>
<p>In boxes on your answer sheet, write</p>
<p><strong>TRUE</strong>               if the statement agrees with the information</p>
<p><strong>FALSE</strong>              if the statement contradicts the information</p>
<p><strong>NOT GIVEN</strong>    if there is no information on this</p>
                                        </div>
                                        <div class="ielts-reading-questions">
                                                                                                                                                                                            <div class="ielts-standalone-q" data-qnum="1"><div class="ielts-q-header"><strong class="ielts-q-badge">1</strong><span class="ielts-q-title"><span>Clippers were originally intended to be used as passenger ships.</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="1" name="question_1" value="TRUE"><span class="ielts-radio-text"><strong>TRUE</strong> </span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="1" name="question_1" value="FALSE"><span class="ielts-radio-text"><strong>FALSE</strong> </span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="1" name="question_1" value="NOT GIVEN"><span class="ielts-radio-text"><strong>NOT GIVEN</strong> </span></label></div></div><div class="ielts-standalone-q" data-qnum="2"><div class="ielts-q-header"><strong class="ielts-q-badge">2</strong><span class="ielts-q-title"><span><em>Cutty Sark</em> was given the name of a character in a poem.</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="2" name="question_2" value="TRUE"><span class="ielts-radio-text"><strong>TRUE</strong> </span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="2" name="question_2" value="FALSE"><span class="ielts-radio-text"><strong>FALSE</strong> </span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="2" name="question_2" value="NOT GIVEN"><span class="ielts-radio-text"><strong>NOT GIVEN</strong> </span></label></div></div><div class="ielts-standalone-q" data-qnum="3"><div class="ielts-q-header"><strong class="ielts-q-badge">3</strong><span class="ielts-q-title"><span>The contract between John Willis and Scott & Linton favoured Willis.</span></div><div class="ielts-radio-group"><label c