-- Section 1342: Reading Passage 2: SAVING THE SOIL
INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(1342, 134, 'reading', 'Reading Passage 2: SAVING THE SOIL', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
                                            Questions 14-17                                                                                                                                                
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <div class="ielts-reading-section-content-wrapper"><p>Complete the summary below.</p>
<p>Write <strong>ONE WORD ONLY</strong> from the passage for each answer.</p>
<p><em>Write your answers in boxes on your answer sheet.</em></p>
<p class="ielts-reading-passage-subhead"><strong><strong>Why soil degradation could be a disaster for humans</strong></strong></p>
<p>Healthy soil contains a large variety of bacteria and other microorganisms, as well as plant remains and <span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">14</strong><input type="text" data-qnum="14" name="question_14" class="ielts-inline-input" placeholder="[14] javob..." autocomplete="off" spellcheck="false"></span></span>. It provides us with food and also with antibiotics, and its function in storing <span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">15</strong><input type="text" data-qnum="15" name="question_15" class="ielts-inline-input" placeholder="[15] javob..." autocomplete="off" spellcheck="false"></span></span> has a significant effect on the climate. In addition, it prevents damage to property and infrastructure because it holds <span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">16</strong><input type="text" data-qnum="16" name="question_16" class="ielts-inline-input" placeholder="[16] javob..." autocomplete="off" spellcheck="false"></span></span>.</p>
<p>If these microorganisms are lost, soil may lose its special properties. The main factor contributing to soil degradation is the <span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">17</strong><input type="text" data-qnum="17" name="question_17" class="ielts-inline-input" placeholder="[17] javob..." autocomplete="off" spellcheck="false"></span></span> carried out by humans.</p>
</div>                                        </div>
                                        <div class="ielts-reading-questions">
                                                                                                                                                                                            <div class="ielts-reading-question-item">
                                                                                                    
